 if(shape==='orbit')return '<circle cx="100" cy="100" r="60" fill="none" stroke="var(--toy-base)" stroke-width="17"/>'+[0,60,120,180,240,300].map(a=>'<g transform="rotate('+a+' 100 100)"><rect x="92" y="37" width="16" height="63" rx="8"/><circle cx="100" cy="39" r="20"/></g>').join('');
